CREATE OR REPLACE FUNCTION app_internal.check_continuity_review_authority() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_role text; v_supervisor uuid; BEGIN IF NEW.status IN ('approved','rejected') THEN SELECT role INTO v_role FROM public.profiles WHERE id=auth.uid() AND company_id=NEW.company_id; SELECT supervisor_id INTO v_supervisor FROM public.personnel_records WHERE id=NEW.personnel_id AND company_id=NEW.company_id; IF NOT coalesce(auth.uid() <> NEW.submitted_by AND (v_role IN ('company_admin','safety_director','qc_inspector') OR (v_role='field_supervisor' AND v_supervisor=auth.uid())),false) THEN RAISE EXCEPTION 'Independent authorized review required'; END IF; END IF; RETURN NEW; END; $$; DROP TRIGGER IF EXISTS check_continuity_review_authority ON public.continuity_submissions; CREATE TRIGGER check_continuity_review_authority BEFORE INSERT OR UPDATE ON public.continuity_submissions FOR EACH ROW EXECUTE FUNCTION app_internal.check_continuity_review_authority();